from typing import List

class Solution:
    def average(self, salary: List[int]) -> float:
        # Remove the minimum and maximum salaries
        filtered_salary = [s for s in salary if s != min(salary) and s != max(salary)]

        # Calculate the average of the remaining salaries
        return sum(filtered_salary) / len(filtered_salary)
